	public String resetInfobarAnimation(PrintWriter print_writer, String which_frame)
			throws InterruptedException, IOException {

		switch (which_frame.toUpperCase()) {
		case "FF_FRAME":
			if(!infobar.isInfobar_down()) {
				if (infobar.isInfobar_on_screen() == true) {
					AnimateOutGraphics(print_writer, "FF_OUT");
					which_graphic_on_screen = "SCOREBUG";
				}
			}else {
				if (infobar.isInfobar_on_screen() == true) {
					which_graphic_on_screen = "SCOREBUG";
				}
			}
			break;
		case "LT_FRAME":
			if(!infobar.isIs_ticker_shrink() && !infobar.isInfobar_down()) {
				if (infobar.isInfobar_on_screen() == true) {
					infobar.setIs_ticker_shrink(false);
					AnimateOutGraphics(print_writer, "LT_OUT");
					which_graphic_on_screen = "SCOREBUG";
				}
			}else {
				if (infobar.isInfobar_on_screen() == true) {
					which_graphic_on_screen = "SCOREBUG";
				}
			}
			break;
		case "BUGS":
			if (infobar.isInfobar_on_screen() == true) {
				which_graphic_on_screen = "SCOREBUG";
			}
			break;	
		}
		return "";
	}

