	public void populateBowlPopUp(PrintWriter print_writer,String viz_scene, int whichInning, String strikeRateOrRuns, int playerId, int whichSide, MatchAllData match,CricketService cricketService, String session_selected_broadcaster, Configuration config) {
		if (match == null) {
			System.out.println("ERROR: populateScorecard -> Match is null"); // DJ change all 'this.status' to 'system printout'
		} else if (match.getMatch().getInning() == null) {
			System.out.println("ERROR: populateScorecard -> Scorecard's inning is null");
		} else {
			Inning inning = match.getMatch().getInning().stream().filter(inn -> inn.getInningNumber() == whichInning).findAny().orElse(null);
			Player player = cricketService.getAllPlayer().stream().filter(plyr -> plyr.getPlayerId() == playerId).findAny().orElse(null);
			Team team =  cricketService.getTeams().stream().filter(tm -> tm.getTeamId() == player.getTeamId()).findAny().orElse(null);
			
			print_writer.println("-1 RENDERER*TREE*$Main$Select*FUNCTION*Omo*vis_con SET 1\0");
			print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$band$img_Text2$txt_Header*GEOM*TEXT SET "+player.getFull_name()+"\0");
			print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$band$img_Text2*TEXTURE*IMAGE SET "+text_path+"2/"+team.getTeamBadge()+"\0");
			print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$band$img_Base2*TEXTURE*IMAGE SET "+base_path+"2/"+team.getTeamBadge()+"\0");
			print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$base$img_base1*TEXTURE*IMAGE SET "+base_path+"1/"+team.getTeamBadge()+"\0");
			
			print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$Badge$img_Badges*TEXTURE*IMAGE SET "+logo_path+team.getTeamBadge()+"\0");
			
			print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$band$img_Base2*TEXTURE*IMAGE SET "+base_path+"2/"+team.getTeamBadge()+"\0");
			print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$Sub_Header$img_Text1*TEXTURE*IMAGE SET "+text_path+"1/"+team.getTeamBadge()+"\0");
			
			print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$ScoreGrp$img_Text1*TEXTURE*IMAGE SET "+text_path+"1/"+team.getTeamBadge()+"\0");
			
			
			for(BowlingCard boc : inning.getBowlingCard()) {
				if(boc.getPlayerId() == playerId) {
					switch (strikeRateOrRuns.toUpperCase()) {
					case "ECONOMY":
						print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$Sub_Header$StatHead1*GEOM*TEXT SET " + "ECONOMY" + "\0");
						print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$ScoreGrp$Seperator*ACTIVE SET 0\0");
						print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$ScoreGrp$Score*GEOM*TEXT SET " + 
								CricketFunctions.getEconomy(boc.getRuns(), (boc.getOvers()*6)+(boc.getBalls()), 2, "-")+"\0");
						print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$ScoreGrp$Balls*GEOM*TEXT SET \0");
						break;

					case "FIGURES":
						print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$Sub_Header$StatHead1*GEOM*TEXT SET " + "THIS MATCH"+"\0");
						print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$ScoreGrp$Seperator*ACTIVE SET 1\0");
						print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$ScoreGrp$Score*GEOM*TEXT SET " + 
								boc.getWickets() + "-" + boc.getRuns() + "\0");
						if(boc.getOvers() == 0 && boc.getBalls() >= 0) {
							print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$ScoreGrp$Balls*GEOM*TEXT SET " + 
									CricketFunctions.OverBalls(boc.getOvers(), boc.getBalls()) + " OVERS" + "\0");
						}else if(boc.getOvers() == 1 && boc.getBalls() == 0) {
							print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$ScoreGrp$Balls*GEOM*TEXT SET " + 
									CricketFunctions.OverBalls(boc.getOvers(), boc.getBalls()) + " OVER" + "\0");
						}else if(boc.getOvers() == 1 && boc.getBalls() > 0) {
							print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$ScoreGrp$Balls*GEOM*TEXT SET " + 
									CricketFunctions.OverBalls(boc.getOvers(), boc.getBalls()) + " OVERS" + "\0");
						}else {
							print_writer.println("-1 RENDERER*TREE*$Main$Select$POP_UP$ScoreGrp$Balls*GEOM*TEXT SET " + 
									CricketFunctions.OverBalls(boc.getOvers(), boc.getBalls()) + " OVERS" + "\0");
						}
						
						break;
					}
				}
			}
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.tga In 1.100 \0");
		}
	}
	
