	public void populateBugMultipartnership(PrintWriter print_writer, String viz_scene, int whichinning,
			int partnership, MatchAllData match, String session_selected_broadcaster) throws Exception {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: Partnership inning is null";
		} else {
			
			List<Partnership> Partnership ;
			
			print_writer.println("-1 RENDERER*TREE*$Main$Bug_ALL$Select*FUNCTION*Omo*vis_con SET 3 \0");
			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getInningNumber() == whichinning) {
					Partnership = CricketFunctions.ConcussedPartnership(match.getMatch(), inn.getInningNumber());
					String Left_Batsman = "", Right_Batsman = "";

					for (BattingCard hs : inn.getBattingCard()) {
						if (hs.getPlayerId() == Partnership.get(partnership - 1).getFirstBatterNo()) {
							Left_Batsman = hs.getPlayer().getTicker_name();
						}
						if (hs.getPlayerId() == Partnership.get(partnership - 1).getSecondBatterNo()) {
							Right_Batsman = hs.getPlayer().getTicker_name();
						}
					}
					print_writer.println(
							"-1 RENDERER*TREE*$Main$Bug_ALL$Select$Double$All$DataGrpAll$img_Text1$PlayerNameGrp$Info01*GEOM*TEXT SET "
									+ Left_Batsman + " & " + Right_Batsman + "\0");
					print_writer.println(
							"-1 RENDERER*TREE*$Main$Bug_ALL$Select$Double$All$DataGrpAll$img_Text1$PlayerNameGrp$Info02*GEOM*TEXT SET "
									+ "" + "\0");

					print_writer.println(
							"-1 RENDERER*TREE*$Main$Bug_ALL$Select$Double$All$Logo$TeamBageGrp$LogoBase$img_Base2*TEXTURE*IMAGE SET "
									+ base_path + "2/"
									+ match.getMatch().getInning().get(whichinning - 1).getBatting_team().getTeamBadge()
									+ " \0");
					print_writer.println(
							"-1 RENDERER*TREE*$Main$Bug_ALL$Select$Double$All$Logo$TeamBageGrp$Select_BadgeType$img_Badges*TEXTURE*IMAGE SET "
									+ logo_path
									+ match.getMatch().getInning().get(whichinning - 1).getBatting_team().getTeamBadge()
									+ "\0");
					print_writer.println(
							"-1 RENDERER*TREE*$Main$Bug_ALL$Select$Double$All$Logo$TeamBageGrp$img_Badges*TEXTURE*IMAGE SET "
									+ logo_path
									+ match.getMatch().getInning().get(whichinning - 1).getBatting_team().getTeamBadge()
									+ "\0");

					if(Partnership.get(partnership - 1).getPartnershipNumber()==0) {
						print_writer.println("-1 RENDERER*TREE*$Main$Bug_ALL$Select$Double$All$DataGrpAll$img_Text1$PlayerNameGrp$Info03*GEOM*TEXT SET "
								+" PARTNERSHIP" + "\0");
						print_writer.println("-1 RENDERER*TREE*$Main$Bug_ALL$Select$Double$All$DataGrpAll$img_Text1$PlayerNameGrp$group$Info04*GEOM*TEXT SET \0");
					}else {
						print_writer.println("-1 RENDERER*TREE*$Main$Bug_ALL$Select$Double$All$DataGrpAll$img_Text1$PlayerNameGrp$Info03*GEOM*TEXT SET "
								+ CricketFunctions.ordinal(Partnership.get(partnership - 1).getPartnershipNumber()) +" WICKET PARTNERSHIP" + "\0");
						print_writer.println("-1 RENDERER*TREE*$Main$Bug_ALL$Select$Double$All$DataGrpAll$img_Text1$PlayerNameGrp$group$Info04*GEOM*TEXT SET "
								+ Partnership.get(partnership - 1).getTotalRuns() +((partnership - 1)==Partnership.size()-1? "*":"")+ " ("
								+ Partnership.get(partnership - 1).getTotalBalls() + ")" + "\0");
					}
					print_writer.println("-1 RENDERER*TREE*$Main$Bug_ALL$Select$Double$All$DataGrpAll$img_Text1$PlayerNameGrp$group$Info05*GEOM*TEXT SET "
									+ " " + "\0");

				}
			}
		}
		print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.tga In 0.800 \0");
		TimeUnit.MILLISECONDS.sleep(100);
	}

