	public void populateInfobarDirector(PrintWriter print_writer, String Dir_value, String session_selected_broadcaster)
			throws InterruptedException {

		switch (Dir_value.toUpperCase()) {
		case "FOURS":
			print_writer.println("-1 RENDERER*FRONT_LAYER*STAGE*DIRECTOR*Section2$FourIn START \0");
			break;

		case "SIXES":
			print_writer.println("-1 RENDERER*FRONT_LAYER*STAGE*DIRECTOR*Section2$SixIn START \0");
			break;
		case "WICKET":
			print_writer.println("-1 RENDERER*FRONT_LAYER*STAGE*DIRECTOR*Section2$WicketIn START \0");
			break;
		case "FREE-HIT":
			if (infobar.getLast_top_section() != null && !infobar.getLast_top_section().trim().isEmpty()) {
				switch (infobar.getLast_top_section().toUpperCase()) {
				case CricketUtil.TOSS:
					processAnimation(print_writer, "Section2$TossOut", "START", broadcaster);
					break;
				case "CRR":
					processAnimation(print_writer, "Section2$RunRateOut", "START", broadcaster);
					break;
				case "RRR":
					processAnimation(print_writer, "Section2$ReqRunRateOut", "START", broadcaster);
					break;
				case "NEXT_TO_BAT":
					processAnimation(print_writer, "Section2$NextInOut", "START", broadcaster);
					break;
				case "TARGET":
					processAnimation(print_writer, "Section2$TargetOut", "START", broadcaster);
					break;
				case "PARTNERSHIP":
					processAnimation(print_writer, "Section2$PartnershipOut", "START", broadcaster);
					break;

				}
				print_writer.println("-1 RENDERER*FRONT_LAYER*STAGE*DIRECTOR*EventAnimation$FreeHitIn START \0");
			}
			infobar.setDirecter_section("FREE-HIT");
			break;
		}
	}

	public void populateInfobarSponsor(PrintWriter print_writer, String Sponsor_value,
			String session_selected_broadcaster) throws InterruptedException {

		if (infobar.getLast_top_section() != null && !infobar.getLast_top_section().trim().isEmpty()) {
			switch (infobar.getLast_top_section().toUpperCase()) {
			case CricketUtil.TOSS:
				previous_middle_data = CricketUtil.TOSS;
				processAnimation(print_writer, "Section2$TossOut", "START", broadcaster);
				break;
			case "SUPER_OVER":
				previous_middle_data = "SUPER_OVER";
				processAnimation(print_writer, "Section2$TossOut", "START", broadcaster);
				break;
			case "TOURNAMENT":
				previous_middle_data = "TOURNAMENT";
				processAnimation(print_writer, "Section2$TossOut", "START", broadcaster);
				break;	
			case "CRR":
				previous_middle_data = "CRR";
				processAnimation(print_writer, "Section2$RunRateOut", "START", broadcaster);
				break;
			case "RRR":
				previous_middle_data = "RRR";
				processAnimation(print_writer, "Section2$ReqRunRateOut", "START", broadcaster);
				break;
			case "NEXT_TO_BAT":
				previous_middle_data = "NEXT_TO_BAT";
				processAnimation(print_writer, "Section2$NextInOut", "START", broadcaster);
				break;
			case "TARGET":
				previous_middle_data = "TARGET";
				processAnimation(print_writer, "Section2$TargetOut", "START", broadcaster);
				break;
			case "PARTNERSHIP":
				previous_middle_data = "PARTNERSHIP";
				processAnimation(print_writer, "Section2$PartnershipOut", "START", broadcaster);
				break;
			default:
				print_writer.println("-1 RENDERER*FRONT_LAYER*STAGE*DIRECTOR*SponsorsOut START \0");
				TimeUnit.MILLISECONDS.sleep(400);
				break;

			}
		}
		print_writer.println(
				"-1 RENDERER*FRONT_LAYER*TREE*$Main$All$Section2$StatGRP$noname$Sponsors$img_Spnsor*TEXTURE*IMAGE SET "
						+ "C:\\Images\\LLC\\Sponsors_LLC\\" + Sponsor_value + ".png" + " \0");
		print_writer.println("-1 RENDERER*FRONT_LAYER*STAGE*DIRECTOR*SponsorsIn START \0");
		infobar.setLast_top_section(Sponsor_value);
	}

