	public void populateLtBowlerDetails(PrintWriter print_writer, String viz_scene, int whichInning, int PlayerId,
			MatchAllData match, String session_selected_broadcaster) {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: PlayerStats's inning is null";
		} else {
			int total_inn = 0;

			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getInningStatus() != null) {
					total_inn = total_inn + 1;
				}
			}
			if (total_inn > 0 && whichInning > total_inn) {
				whichInning = total_inn;
			}
			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getInningNumber() == whichInning) {
					for (BowlingCard boc : inn.getBowlingCard()) {
						if (boc.getPlayerId() == PlayerId) {
							print_writer.println("-1 RENDERER*TREE*$Main$All$DataAll$All_Name$PlayerName*GEOM*TEXT SET "
									+ boc.getPlayer().getFull_name() + "\0");
							print_writer.println(
									"-1 RENDERER*TREE*$Main$All$DataAll$ROW1$All_StatsVal$StatHead_GRP$StatAll1$StatHead02*GEOM*TEXT SET "
											+ boc.getOvers() + "\0");
							print_writer.println(
									"-1 RENDERER*TREE*$Main$All$DataAll$ROW1$All_StatsVal$StatValues_GRP$StatValue1$StatValue1B*GEOM*TEXT SET "
											+ boc.getDots() + "\0");
							print_writer.println(
									"-1 RENDERER*TREE*$Main$All$DataAll$ROW1$All_StatsVal$StatValues_GRP$StatValue2$StatValue1B*GEOM*TEXT SET "
											+ boc.getRuns() + "\0");
							print_writer.println(
									"-1 RENDERER*TREE*$Main$All$DataAll$ROW1$All_StatsVal$StatValues_GRP$StatValue3$StatValue1B*GEOM*TEXT SET "
											+ boc.getWickets() + "\0");
							print_writer.println(
									"-1 RENDERER*TREE*$Main$All$DataAll$ROW1$All_StatsVal$StatValues_GRP$StatValue3$StatValue1B*GEOM*TEXT SET "
											+ boc.getEconomyRate() + "\0");
						}
					}
					break;
				}
			}

		}
	}

	public void populateLandMark(PrintWriter print_writer, String viz_scene, int whichInning, String statType,
			int playerId, MatchAllData match, String session_selected_broadcaster, Configuration config) {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else {
			this.status = CricketUtil.SUCCESSFUL;
			// String Home_or_Away="";
			for (Inning inn : match.getMatch().getInning()) {
				if (inn.getInningNumber() == whichInning) {

					switch (statType.toUpperCase()) {
					case "BATSMAN":
						for (BattingCard bc : inn.getBattingCard()) {
							if (playerId == bc.getPlayerId()) {

								print_writer.println(
										"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON tLastName SET "
												+ bc.getPlayer().getFirstname() + "\0");
								print_writer.println(
										"-1 RENDERER*TREE*$Main$AllGrp$All$PlayerProfile$Data$Mile$Data$ValueGrp$Runs$IconOmo*FUNCTION*Omo*vis_con SET 1 \0");
								print_writer.println(
										"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON tFistName SET "
												+ bc.getPlayer().getFirstname() + "\0");
								print_writer.println(
										"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON tLastName SET "
												+ bc.getPlayer().getSurname() + "\0");

								if (bc.getStatus().equals(CricketUtil.OUT)) {
									print_writer.println(
											"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON tRuns SET "
													+ bc.getRuns() + "\0");
								} else {
									print_writer.println(
											"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON tRuns SET "
													+ bc.getRuns() + "*" + "\0");
								}

								print_writer
										.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON tBalls SET "
												+ bc.getBalls() + "\0");

								print_writer.println(
										"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "lgTeamLogo"
												+ " SET " + logo_path + inn.getBatting_team().getTeamBadge() + "\0");
								if (config.getPrimaryIpAddress().equalsIgnoreCase("LOCALHOST")) {
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "lgImage" + " SET " + photo_path + inn.getBatting_team().getTeamName4()
											+ "\\\\" + bc.getPlayer().getPhoto() + ".png" + "\0");
								} else {
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "lgImage" + " SET " + "\\\\" + config.getPrimaryIpAddress() + "\\\\"
											+ local_photo_path + inn.getBatting_team().getTeamName4() + "\\\\"
											+ bc.getPlayer().getPhoto() + ".png" + "\0");
								}
							}
						}

						break;
					case "BOWLER":
						for (BowlingCard boc : inn.getBowlingCard()) {
							if (playerId == boc.getPlayerId()) {

								print_writer.println(
										"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON tLastName SET "
												+ boc.getPlayer().getFirstname() + "\0");
								print_writer.println(
										"-1 RENDERER*TREE*$Main$AllGrp$All$PlayerProfile$Data$Mile$Data$ValueGrp$Runs$IconOmo*FUNCTION*Omo*vis_con SET 2 \0");
								print_writer.println(
										"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON tFistName SET "
												+ boc.getPlayer().getFirstname() + "\0");
								print_writer.println(
										"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON tLastName SET "
												+ boc.getPlayer().getSurname() + "\0");

								print_writer
										.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON tRuns SET "
												+ boc.getWickets() + "-" + boc.getRuns() + "\0");
								print_writer
										.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON tBalls SET "
												+ CricketFunctions.OverBalls(boc.getOvers(), boc.getBalls()) + " Overs"
												+ "\0");

								print_writer.println(
										"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "lgTeamLogo"
												+ " SET " + logo_path + inn.getBowling_team().getTeamBadge() + "\0");
								if (config.getPrimaryIpAddress().equalsIgnoreCase("LOCALHOST")) {
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "lgImage" + " SET " + photo_path + inn.getBowling_team().getTeamName4()
											+ "\\\\" + boc.getPlayer().getPhoto() + ".png" + "\0");
								} else {
									print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON "
											+ "lgImage" + " SET " + "\\\\" + config.getPrimaryIpAddress() + "\\\\"
											+ local_photo_path + inn.getBowling_team().getTeamName4() + "\\\\"
											+ boc.getPlayer().getPhoto() + ".png" + "\0");
								}

							}
						}
						break;
					}
				}
			}
		}
		print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
				+ " C:/Temp/Preview.tga In 3.100 In$DataIn 1.660 In$Data1In 1.700 \0");
	}

