	public void populateLtManhattan(PrintWriter print_writer, String viz_scene, int whichInning, MatchAllData match,
			String broadcaster) throws InterruptedException {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (whichInning == 0) {
			this.status = "ERROR: Inning is null";
		} else {

			int maxRuns = 0, runsIncr = 0;
			long lngth = 0;

			print_writer.println(
					"-1 RENDERER*TREE*$Main$AllGrp$All$Manhattan$Data$Header$TeamNameGrp$FirstName*GEOM*TEXT SET " + " "
							+ " \0");

			for (int j = 0; j < CricketFunctions
					.getOverByOverData(match, whichInning, "MANHATTAN", match.getEventFile().getEvents()).size(); j++) {
				if (CricketFunctions
						.getOverByOverData(match, whichInning, "MANHATTAN", match.getEventFile().getEvents()).get(j)
						.getInningNumber() == whichInning) {
					if (Integer.valueOf(CricketFunctions
							.getOverByOverData(match, whichInning, "MANHATTAN", match.getEventFile().getEvents()).get(j)
							.getOverTotalRuns()) > maxRuns) {
						maxRuns = Integer.valueOf(CricketFunctions
								.getOverByOverData(match, whichInning, "MANHATTAN", match.getEventFile().getEvents())
								.get(j).getOverTotalRuns()); // 33 runs came off 34th over
					}

					while (maxRuns % 3 != 0) { // 5 label in y-axis
						maxRuns = maxRuns + 1; // keep incrementing till max runs is divisible by 5. maxRuns = 35
					}
				}
			}

			for (int i = 0; i < 3; i++) {
				runsIncr = maxRuns / 3; // 35/5=7 -> Y axis will be plot like 6,12,18,24,30 & 36
				print_writer.println("-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$Mann$Man20$lines$PlayerNameGrp$Row"
						+ (3 - i) + "$RowAni$Runs*GEOM*TEXT SET " + runsIncr * (i + 1) + "\0");
			}

			for (int j = 0; j <= match.getSetup().getMaxOvers(); j++) {
				print_writer.println("-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$Mann$Man20$BarGrp$BarAll$Bar" + (j)
						+ "*ACTIVE SET 0" + "\0");
				print_writer.println("-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$Mann$Man20$BarGrp$Wickets$Wkt" + (j)
						+ "*FUNCTION*Omo*vis_con SET " + "0" + " \0");

				if (j < CricketFunctions
						.getOverByOverData(match, whichInning, "MANHATTAN", match.getEventFile().getEvents()).size()) {
					lngth = ((14 * Integer.valueOf(CricketFunctions
							.getOverByOverData(match, whichInning, "MANHATTAN", match.getEventFile().getEvents()).get(j)
							.getOverTotalRuns())) / maxRuns); // 32 is max value of each bar
					print_writer.println("-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$Mann$Man20$BarGrp$BarAll$Bar"
							+ (j) + "*ACTIVE SET 1" + "\0");
					print_writer.println(
							"-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$Mann$Man20$BarGrp$BarAll*FUNCTION*BarValues*Bar_Value__"
									+ (j) + " SET " + lngth + "\0");

					if (CricketFunctions
							.getOverByOverData(match, whichInning, "MANHATTAN", match.getEventFile().getEvents()).get(j)
							.getOverTotalWickets() > 0) {
						print_writer
								.println(
										"-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$Mann$Man20$BarGrp$Wickets$Wkt"
												+ (j) + "*FUNCTION*Omo*vis_con SET "
												+ Integer.valueOf(CricketFunctions
														.getOverByOverData(match, whichInning, "MANHATTAN",
																match.getEventFile().getEvents())
														.get(j).getOverTotalWickets())
												+ " \0");
					} else {
						print_writer
								.println("-1 RENDERER*TREE*$Main$All_Grp$PositionY$All$Mann$Man20$BarGrp$Wickets$Wkt"
										+ (j) + "*FUNCTION*Omo*vis_con SET " + "0" + " \0");
					}

				} else {
					print_writer.println("-1 RENDERER*TREE*$Main$AllGrp$PositionY$All$Mann$Man20$BarGrp$BarAll$Bar"
							+ (j) + "*ACTIVE SET 0" + "\0");
				}
			}
		}
//		print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.jpg In 2.700 In$DataIn1 0.956 In$DataIn2 0.356 \0");		
		TimeUnit.SECONDS.sleep(1);
	}

