	public void populateFixturesAndResult(PrintWriter print_writer, String viz_scene, int teamId, List<Team> team, List<Fixture> fixture,
			String broadcaster, MatchAllData match,List<VariousText> vt) throws InterruptedException {
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else {
			Calendar cal_apl = Calendar.getInstance();
			cal_apl.add(Calendar.DATE, 0);
			int size = 0;
			List<Fixture> fixtureList = new ArrayList<Fixture>();
			Team tm = team.stream().filter(teams->teams.getTeamId()==teamId).findAny().orElse(null);
			
			print_writer.println(
					"-1 RENDERER*TREE*$Main$Teams$Side1$TeamColourBase2$img_Base2*TEXTURE*IMAGE SET "
							+ base_path + "2/" + tm.getTeamBadge() + " \0");
			print_writer.println(
					"-1 RENDERER*TREE*$Main$Teams$Side1$BaseOut$img_Base1*TEXTURE*IMAGE SET "
							+ base_path + "1/" + tm.getTeamBadge() + " \0");
			
			print_writer.println("-1 RENDERER*TREE*$Main$Teams$FooterGrp$txt_Footer*GEOM*TEXT SET \0");
			
			print_writer.println("-1 RENDERER*TREE*$Main$Teams$Side1$HeaderAllGrp$txt_Text1*GEOM*TEXT SET " + tm.getTeamName2() + " \0");
			print_writer.println("-1 RENDERER*TREE*$Main$Teams$Side1$HeaderAllGrp$txt_Text2*GEOM*TEXT SET " + tm.getTeamName3() + " \0");
			
			for (VariousText vartext : vt) {
				if (vartext.getVariousType().equalsIgnoreCase("FIXTUREHEADER")
						&& vartext.getUseThis().toUpperCase().equalsIgnoreCase(CricketUtil.YES)) {
					print_writer.println("-1 RENDERER*TREE*$Main$Teams$Side1$HeaderAllGrp$txt_SubHeader*GEOM*TEXT SET " + 
						vartext.getVariousText() + " \0");
					 
					break;
				} else if (vartext.getVariousType().equalsIgnoreCase("FIXTUREHEADER")
						&& vartext.getUseThis().toUpperCase().equalsIgnoreCase(CricketUtil.NO)) {
					print_writer.println("-1 RENDERER*TREE*$Main$Teams$Side1$HeaderAllGrp$txt_SubHeader*GEOM*TEXT SET " + "FIXTURES AND RESULTS" + " \0");
					 
				}
			}
			
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "010" + " SET " + "2" + "\0");
			
			print_writer.println("-1 RENDERER*TREE*$Main$Teams$Side1$TeamColourBase2$img_Badges*TEXTURE*IMAGE SET " + logo_path + tm.getTeamBadge() + " \0");
			print_writer.println("-1 RENDERER*TREE*$Main$Teams$Side1$LogoOut$img_Badges*TEXTURE*IMAGE SET " + logo_path + tm.getTeamBadge() + " \0");

//			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "001-Logo" + " SET " + logo_path + tm.getTeamBadge() + "\0");

			for(Fixture fix : fixture) {
				if(fix.getHometeamid() == teamId || fix.getAwayteamid() == teamId) {
					fixtureList.add(fix);
				}
			}
			String cont = "";
			int omo=0;
			
			for(int i=0; i<fixtureList.size(); i++) {
				if(fixtureList.get(i).getDate().equalsIgnoreCase(new SimpleDateFormat("dd-MM-yyyy").format(cal_apl.getTime()))) {
					omo=1;
					cont="$Highlight";
				}else {
					omo =0;
					cont="$Dehighlight";
					
				}
				
				print_writer.println("-1 RENDERER*TREE*$Main$LineUpImageDataOut$2ColGrp$Row"+(i+1)+cont+"$RowOmo*FUNCTION*Omo*vis_con SET " + omo + "\0");
				
				
				if(fixtureList.get(i).getHometeamid() == teamId) {
					size++;
					print_writer.println("-1 RENDERER*TREE*$Main$LineUpImageDataOut$2ColGrp$Row"+(i+1)+cont+"$StatHead*GEOM*TEXT SET " + "v "+ team.get(fixtureList.get(i).getAwayteamid()-1).getTeamName1() + "\0");
				}else if(fixtureList.get(i).getAwayteamid() == teamId) {
					size++;
					print_writer.println("-1 RENDERER*TREE*$Main$LineUpImageDataOut$2ColGrp$Row"+(i+1)+cont+"$StatHead*GEOM*TEXT SET " + "v "+ team.get(fixtureList.get(i).getHometeamid()-1).getTeamName1() + "\0");
				}
				
				if(fixtureList.get(i).getMargin() != null && !fixtureList.get(i).getMargin().isEmpty()) {
					if(fixtureList.get(i).getWinnerteam() != null && !fixtureList.get(i).getWinnerteam().isEmpty()) {
						if(fixtureList.get(i).getWinnerteam().equalsIgnoreCase(tm.getTeamName1())) {
							print_writer.println("-1 RENDERER*TREE*$Main$LineUpImageDataOut$2ColGrp$Row"+(i+1)+cont+"$StatValue1*GEOM*TEXT SET " + "WON BY " + fixtureList.get(i).getMargin() + "\0");
//							print_writer.println("-1 RENDERER*TREE*$Main$LineUpImageDataOut$2ColGrp$Row"+(i+1)+cont+"$StatValue2*GEOM*TEXT SET " + fixtureList.get(i).getMargin() + "\0");
						}else {
							print_writer.println("-1 RENDERER*TREE*$Main$LineUpImageDataOut$2ColGrp$Row"+(i+1)+cont+"$StatValue1*GEOM*TEXT SET " + "LOST BY " + fixtureList.get(i).getMargin() + "\0");
//							print_writer.println("-1 RENDERER*TREE*$Main$LineUpImageDataOut$2ColGrp$Row"+(i+1)+cont+"$StatValue2*GEOM*TEXT SET " + fixtureList.get(i).getMargin() + "\0");
						}
					}else {
						print_writer.println("-1 RENDERER*TREE*$Main$LineUpImageDataOut$2ColGrp$Row"+(i+1)+cont+"$StatValue1*GEOM*TEXT SET " + fixtureList.get(i).getMargin() + "\0");
//						print_writer.println("-1 RENDERER*TREE*$Main$LineUpImageDataOut$2ColGrp$Row"+(i+1)+cont+"$StatValue2*GEOM*TEXT SET " + "" + "\0");
					}
				}else {
					
					if(fixtureList.get(i).getDate().equalsIgnoreCase(new SimpleDateFormat("dd-MM-yyyy").format(cal_apl.getTime()))) {
						print_writer.println("-1 RENDERER*TREE*$Main$LineUpImageDataOut$2ColGrp$Row"+(i+1)+cont+"$StatValue1*GEOM*TEXT SET " + "TODAY" + "\0");
//						print_writer.println("-1 RENDERER*TREE*$Main$LineUpImageDataOut$2ColGrp$Row"+(i+1)+cont+"$StatValue2*GEOM*TEXT SET " + "" + "\0");
					}else {
						print_writer.println("-1 RENDERER*TREE*$Main$LineUpImageDataOut$2ColGrp$Row"+(i+1)+cont+"$StatValue1*GEOM*TEXT SET " + CricketFunctions.ordinal(Integer.valueOf(fixtureList.get(i).getDate().split("-")[0]))
						+ " " + Month.of(Integer.valueOf(fixtureList.get(i).getDate().split("-")[1])).getDisplayName(TextStyle.FULL, Locale.ENGLISH).toUpperCase() + "\0");
//						print_writer.println("-1 RENDERER*TREE*$Main$LineUpImageDataOut$2ColGrp$Row"+(i+1)+cont+"$StatValue2*GEOM*TEXT SET " + "" + "\0");
						
					}
				}
				print_writer.println("-1 RENDERER*TREE*$Main$LineUpImageDataOut$2ColGrp$Row"+(i+1)+"$RowOmo*FUNCTION*Omo*vis_con SET " + omo + "\0");
//				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "HighlightSelection" + " SET " + omo + "\0");
			}
			
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "002" + " SET OPPOSITION\0");
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "003" + " SET DATE/RESULTS\0");
			
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "009" + " SET " + (size-1) + "\0");
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.tga Default 2.140 Default$In 2.116 "
					+ "Default$In$DataaaIn 2.116 Default$In$In 1.500 Default$In$In1 1.500 Default$In$In2 1.500 \0");
			TimeUnit.MILLISECONDS.sleep(200);	
		}
	}
	public void populateBestStrike(PrintWriter print_writer,String viz_scene,List<Tournament> tournament,List<Team> team,MatchAllData match, String broadcaster, Configuration config) 
	{
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: Leaderboard inning is null";
		} else {
			this.status = CricketUtil.SUCCESSFUL;
			int row_no=0;

			print_writer.println(
					"-1 RENDERER*TREE*$Main$Teams$Side1$TeamColourBase2$img_Base2*TEXTURE*IMAGE SET "
							+ base_path + "2/" + "TLogo" + " \0");
			print_writer.println(
					"-1 RENDERER*TREE*$Main$Teams$Side1$BaseOut$img_Base1*TEXTURE*IMAGE SET "
							+ base_path + "1/" + "TLogo" + " \0");
			print_writer.println("-1 RENDERER*TREE*$Main$Teams$Side1$TeamColourBase2$img_Badges*TEXTURE*IMAGE SET " + logo_path + "TLogo" + " \0");
			print_writer.println("-1 RENDERER*TREE*$Main$Teams$Side1$LogoOut$img_Badges*TEXTURE*IMAGE SET " + logo_path + "TLogo" + " \0");

			
			Collections.sort(tournament,new CricketFunctions.BestBatsmanStrikeRateComparator());
			
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "000-Header" + " SET " + " " + "\0");
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "000-Header" + " SET " + " " + "\0");
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "000-Header02" + " SET " + "BEST STRIKE RATE" + "\0");
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "000-SubHeader" + " SET " + match.getSetup().getTournament() + "\0");
			print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$RowOmo*FUNCTION*Omo*vis_con SET 4\0");
			
			print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$4ColGrp$StatHeadGrp$StatHead*GEOM*TEXT SET \0");
			print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$4ColGrp$StatHeadGrp$StatValue1*GEOM*TEXT SET TEAM\0");
			print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$4ColGrp$StatHeadGrp$StatValue2*GEOM*TEXT SET RUNS\0");
			print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$4ColGrp$StatHeadGrp$StatValue3*GEOM*TEXT SET S/R\0");
			
			for(int i = 0; i <= tournament.size() - 1 ; i++) {
				if(tournament.get(i).getBallsFaced() >= 60) {
					row_no = row_no + 1;
					if(row_no < 8) {
						
						print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$4ColGrp$4Col*FUNCTION*Omo*vis_con SET " + (row_no-1) + "\0");
						
						print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$4ColGrp$4Col$Row" + row_no + "$RowOmo*FUNCTION*Omo*vis_con SET 0\0");
						
						print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$4ColGrp$4Col$Row" + row_no + "$RowOmo$Dehighlight$StatHead*GEOM*TEXT SET " + 
								tournament.get(i).getPlayer().getFull_name() + "\0");
						print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$4ColGrp$4Col$Row" + row_no + "$RowOmo$Dehighlight$StatValue1*GEOM*TEXT SET " + 
								team.get(tournament.get(i).getPlayer().getTeamId() - 1).getTeamName3() + "\0");
						
						print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$4ColGrp$4Col$Row" + row_no + "$RowOmo$Dehighlight$StatValue2*GEOM*TEXT SET " + 
								tournament.get(i).getRuns() + "\0");
						
						print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$4ColGrp$4Col$Row" + row_no + "$RowOmo$Dehighlight$StatValue3*GEOM*TEXT SET " + 
								Double.parseDouble(CricketFunctions.generateStrikeRate(tournament.get(i).getRuns(), tournament.get(i).getBallsFaced(), 1)) + "\0");
						
					}
				}
			}
			
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "015-Footer" + " SET " + "MINIMUM 60 BALLS" + "\0");
			
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.tga Default 2.140 Default$In 2.116 "
					+ "Default$In$DataaaIn 2.116 Default$In$In 1.500 Default$In$In1 1.500 Default$In$In2 1.500 \0");
		}
	}
	
