	public void populateTeamHighestTotal(PrintWriter print_writer,String viz_scene,String High_Low,List<Team> team,MatchAllData match, String broadcaster, Configuration config) 
	{
		if (match == null) {
		    this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
		    this.status = "ERROR: Leaderboard inning is null";
		} else {
			
		    this.status = CricketUtil.SUCCESSFUL;
		    int row = 2;
		    switch (High_Low.toUpperCase()) {
			case "HIGHEST": case "LOWEST":
				row = 2;
				print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + row + "ColGrp$StatHeadGrp$StatValue1*GEOM*TEXT SET SCORE\0");
				print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$RowOmo*FUNCTION*Omo*vis_con SET 2\0");
				break;
			default:
				row = 3;
				print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + row + "ColGrp$StatHeadGrp$StatValue1*GEOM*TEXT SET AVERAGE SCORE\0");
				print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + row + "ColGrp$StatHeadGrp$StatValue2*GEOM*TEXT SET AVERAGE WICKETS\0");
				print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$RowOmo*FUNCTION*Omo*vis_con SET 3\0");
				break;	
			}
		    		    
		    print_writer.println("-1 RENDERER*TREE*$Main$Teams$Side1$TeamColourBase2$img_Base2*TEXTURE*IMAGE SET "+ base_path + "2/" + "TLogo" + " \0");
			print_writer.println("-1 RENDERER*TREE*$Main$Teams$Side1$BaseOut$img_Base1*TEXTURE*IMAGE SET "+ base_path + "1/" + "TLogo" + " \0");
			print_writer.println("-1 RENDERER*TREE*$Main$Teams$Side1$TeamColourBase2$img_Badges*TEXTURE*IMAGE SET " + logo_path + "TLogo" + " \0");
			print_writer.println("-1 RENDERER*TREE*$Main$Teams$Side1$LogoOut$img_Badges*TEXTURE*IMAGE SET " + logo_path + "TLogo" + " \0");
			
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "000-Header" + " SET " + " " + "\0");
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "000-Header" + " SET " + " " + "\0");
			
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "000-SubHeader" + " SET " + match.getSetup().getTournament() + "\0");
			
			print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + row + "ColGrp$StatHeadGrp$StatHead*GEOM*TEXT SET \0");
			
			
		    switch (High_Low.toUpperCase()) {
			case "HIGHEST":
				List<String> highestTotal = new ArrayList<>();
				   
			    List<String> sortedScores = CricketFunctions.getTeamScore(team, IndexController.headToHead.getH2hTeam(), match);
			    
				sortedScores.sort((a, b) -> {
			        int scoreA = Integer.parseInt(a.split(" - ")[1]); // Highest score
			        int scoreB = Integer.parseInt(b.split(" - ")[1]);
			        return Integer.compare(scoreB, scoreA); // Descending
			    });

			    // Add sorted data to highestTotal
			    highestTotal.addAll(sortedScores);
			    print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "000-Header02" + " SET " + "HIGHEST SCORE" + "\0");
			    
			    for (int i = 0; i < highestTotal.size(); i++) {
			    	print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + row + "ColGrp$4Col*FUNCTION*Omo*vis_con SET " + i + "\0");
					
					print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + row + "ColGrp$4Col$Row" + (i+1) + "$RowOmo*FUNCTION*Omo*vis_con SET 0\0");
					
					print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + row + "ColGrp$4Col$Row" + (i+1) + "$RowOmo$Dehighlight$StatHead*GEOM*TEXT SET " + 
							highestTotal.get(i).split("-")[0] + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + row + "ColGrp$4Col$Row" + (i+1) + "$RowOmo$Dehighlight$StatValue1*GEOM*TEXT SET " + 
							highestTotal.get(i).split("-")[1] + "\0");
				}
				    
				break;
			case "LOWEST":
				List<String> lowestTotal = new ArrayList<>();
				   
			    List<String> sortedScore = CricketFunctions.getTeamScore(team,  IndexController.headToHead.getH2hTeam(), match);
			    
			    sortedScore.sort((a, b) -> Integer.compare(
			        Integer.parseInt(a.split(" - ")[2]), 
			        Integer.parseInt(b.split(" - ")[2])
			    ));
				
			    lowestTotal.addAll(sortedScore);
			    print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "000-Header02" + " SET " + "LOWEST SCORE" + "\0");
			    
			    for (int i = 0; i < lowestTotal.size(); i++) {
			    	print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + row + "ColGrp$4Col*FUNCTION*Omo*vis_con SET " + i + "\0");
					
					print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + row + "ColGrp$4Col$Row" + (i+1) + "$RowOmo*FUNCTION*Omo*vis_con SET 0\0");
					
					print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + row + "ColGrp$4Col$Row" + (i+1) + "$RowOmo$Dehighlight$StatHead*GEOM*TEXT SET " + 
							lowestTotal.get(i).split("-")[0] + "\0");
					print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + row + "ColGrp$4Col$Row" + (i+1) + "$RowOmo$Dehighlight$StatValue1*GEOM*TEXT SET " + 
							lowestTotal.get(i).split("-")[2] + "\0");
				}
				break;
			case "AVERAGE":
				Map<String ,HeadToHeadTeam> powerplay  = CricketFunctions.getPowerPlayAverage(team, IndexController.headToHead.getH2hTeam(), match);
				
				int[] r = {0,row}; 

				powerplay.entrySet().stream()
				    .sorted((e1, e2) -> {
				        HeadToHeadTeam h1 = e1.getValue();
				        HeadToHeadTeam h2 = e2.getValue();
				        double avg1 = h1.getTotalmatches() == 0 ? 0.0 : (double) h1.getP1_Run() / h1.getTotalmatches();
				        double avg2 = h2.getTotalmatches() == 0 ? 0.0 : (double) h2.getP1_Run() / h2.getTotalmatches();
				        return Double.compare(avg2, avg1); // Descending
				    })
				    .forEach(entry -> {
				        HeadToHeadTeam pp = entry.getValue();
				        int averageRun = pp.getTotalmatches() == 0 ? 0 : (int) pp.getP1_Run() / pp.getTotalmatches();
				        int averageWickets = pp.getTotalmatches() == 0 ? 0 : (int) pp.getP1_Wicket() / pp.getTotalmatches();

				        print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + r[1] + "ColGrp$4Col*FUNCTION*Omo*vis_con SET " + r[0] + "\0");
				        print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + r[1] + "ColGrp$4Col$Row" + (r[0]+1) + "$RowOmo*FUNCTION*Omo*vis_con SET 0\0");
				        print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + r[1] + "ColGrp$4Col$Row" + (r[0]+1) + "$RowOmo$Dehighlight$StatHead*GEOM*TEXT SET " + 
				            pp.getTeam().getTeamName1() + "\0");
				        print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + r[1] + "ColGrp$4Col$Row" + (r[0]+1) + "$RowOmo$Dehighlight$StatValue1*GEOM*TEXT SET " + 
				        	averageRun + "\0");
				        print_writer.println("-1 RENDERER*TREE*$Main$MainGrp$FF_ROWCOL$" + r[1] + "ColGrp$4Col$Row" + (r[0]+1) + "$RowOmo$Dehighlight$StatValue2*GEOM*TEXT SET " + 
				        	averageWickets + "\0");

				        r[0]++;
				    });
				print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "000-Header02" + " SET " + "POWERPLAY AVERAGE SCORE" + "\0");
			    
				break;
			}
		    
			print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "015-Footer" + " SET \0");
			
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.tga Default 2.140 Default$In 2.116 "
					+ "Default$In$DataaaIn 2.116 Default$In$In 1.500 Default$In$In1 1.500 Default$In$In2 1.500 \0");
		    
		    
		}
	}
	
	public void populateSchedule(PrintWriter print_writer, String viz_scene, List<Fixture> fixture, List<Team> team,
			MatchAllData match, String broadcaster) throws ParseException {

		int row_id = 0, omo_num = 0;
		String Date = "", cont_name = "";
		Calendar cal = Calendar.getInstance();
		Date = new SimpleDateFormat("dd-MM-yyyy").format(cal.getTime());

		print_writer.println(
				"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tHeader1" + " SET " + " " + "\0");
		print_writer.println(
				"-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tHeader2" + " SET " + "SCHEDULE" + "\0");
		print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tSumSubHeader" + " SET "
				+ match.getSetup().getTournament() + "\0");

		for (int i = 0; i < fixture.size(); i++) {
			row_id = row_id + 1;
			if (fixture.get(i).getDate().equalsIgnoreCase(Date)) {
				omo_num = 1;
				cont_name = "$Highlight";
			} else {
				omo_num = 0;
				cont_name = "$Dehighlight";
			}

			print_writer.println(
					"-1 RENDERER*TREE*$Main$AllGrp$All$TeamLineup_Both$TeamsAll$TeamDataData$TeamAll1$TeamAll1$Row"
							+ row_id + "$RowAnimation$RowOmo*FUNCTION*Omo*vis_con SET " + String.valueOf(omo_num)
							+ " \0");
			if (fixture.get(i).getMatchnumber() % 2 == 0) {
				print_writer.println(
						"-1 RENDERER*TREE*$Main$AllGrp$All$TeamLineup_Both$TeamsAll$TeamDataData$TeamAll1$TeamAll1$Row"
								+ row_id + "$RowAnimation$RowOmo" + cont_name
								+ "$DateAll$TimeOmo*FUNCTION*Omo*vis_con SET " + "1" + "\0");
			} else {
				print_writer.println(
						"-1 RENDERER*TREE*$Main$AllGrp$All$TeamLineup_Both$TeamsAll$TeamDataData$TeamAll1$TeamAll1$Row"
								+ row_id + "$RowAnimation$RowOmo" + cont_name
								+ "$DateAll$TimeOmo*FUNCTION*Omo*vis_con SET " + "0" + "\0");
			}

			print_writer.println(
					"-1 RENDERER*TREE*$Main$AllGrp$All$TeamLineup_Both$TeamsAll$TeamDataData$TeamAll1$TeamAll1$Row"
							+ row_id + "$RowAnimation$RowOmo" + cont_name + "$DateAll$DateText*GEOM*TEXT SET "
							+ fixture.get(i).getDate() + "\0");
			print_writer.println(
					"-1 RENDERER*TREE*$Main$AllGrp$All$TeamLineup_Both$TeamsAll$TeamDataData$TeamAll1$TeamAll1$Row"
							+ row_id + "$RowAnimation$RowOmo" + cont_name + "$TextAll$NameAll$TeamName1*GEOM*TEXT SET "
							+ team.get(fixture.get(i).getHometeamid() - 1).getTeamName1().toUpperCase() + "\0");
			print_writer.println(
					"-1 RENDERER*TREE*$Main$AllGrp$All$TeamLineup_Both$TeamsAll$TeamDataData$TeamAll1$TeamAll1$Row"
							+ row_id + "$RowAnimation$RowOmo" + cont_name + "$TextAll$NameAll$TeamName2*GEOM*TEXT SET "
							+ team.get(fixture.get(i).getAwayteamid() - 1).getTeamName1().toUpperCase() + "\0");

			if (fixture.get(i).getWinnerteam() != null) {
				if (fixture.get(i).getWinnerteam().toUpperCase()
						.equalsIgnoreCase(team.get(fixture.get(i).getHometeamid() - 1).getTeamName4().toUpperCase())) {
					print_writer.println(
							"-1 RENDERER*TREE*$Main$AllGrp$All$TeamLineup_Both$TeamsAll$TeamDataData$TeamAll1$TeamAll1$Row"
									+ row_id + "$RowAnimation$RowOmo" + cont_name
									+ "$TextAll$ResultOmo*FUNCTION*Omo*vis_con SET " + "1" + "\0");
				} else if (fixture.get(i).getWinnerteam().toUpperCase()
						.equalsIgnoreCase(team.get(fixture.get(i).getAwayteamid() - 1).getTeamName4().toUpperCase())) {
					print_writer.println(
							"-1 RENDERER*TREE*$Main$AllGrp$All$TeamLineup_Both$TeamsAll$TeamDataData$TeamAll1$TeamAll1$Row"
									+ row_id + "$RowAnimation$RowOmo" + cont_name
									+ "$TextAll$ResultOmo*FUNCTION*Omo*vis_con SET " + "2" + "\0");
				}
			} else {
				print_writer.println(
						"-1 RENDERER*TREE*$Main$AllGrp$All$TeamLineup_Both$TeamsAll$TeamDataData$TeamAll1$TeamAll1$Row"
								+ row_id + "$RowAnimation$RowOmo" + cont_name
								+ "$TextAll$ResultOmo*FUNCTION*Omo*vis_con SET " + "0" + "\0");
			}
		}

		print_writer.println("-1 RENDERER*TREE*$Main*FUNCTION*ControlObject*in SET ON " + "tInfo" + " SET "
				+ "TOP FOUR TEAMS QUALIFY FOR THE SEMIS" + "\0");

//		print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.jpg In 2.474 In$DataIn 1.750 \0");

	}

