	public void populateEverestPreview(PrintWriter print_writer, String viz_scene, int which_side, String which_graphic)
			throws InterruptedException {

		if (which_side == 1) {
			switch (which_graphic) {
			case "HOWOUT": case "HOWOUT_QUICK": case "HOWOUT_WITHOUT_FIELDER": case "NAMESUPER": case "FALLOFWICKET": case "NAMESUPER-PLAYER": case "SPLIT":
			case "BATSMANSTATS": case "BOWLERSTATS": case "PLAYERSUMMARY": case "BOWLERDETAILS": case "TEAMSUMMARY": case "PROJECTED": case "BATSMAN_STYLE":
			case "BOWLER_STYLE": case "PLAYERPROFILEBAT": case "PLAYERPROFILE": case "PARTNERSHIP": case "SEASON_PROFILE": case "THISSERIES": case "THISPARTNERSHIP":
			case "NEXT_TO_BAT": case "IMPACT": case "PHASE-WISE": case "PHASE-COMPARISON": case "LT_POINTER":
				print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
						+ " C:/Temp/Preview.tga LT$LTBaseIn 1.800 LT$LTLogoIn 1.500 " + "LT$LTDataIn 2.000 \0");
				TimeUnit.MILLISECONDS.sleep(500);
				break;
			case "BAT-POPUP": case "BOWL-POPUP":
				print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene+ " C:/Temp/Preview.tga In 1.70 In$BatDataIn 1.180\0");
				break;
			}
		} else if (which_side == 2) {
			switch (which_graphic) {
			case "HOWOUT": case "HOWOUT_QUICK": case "HOWOUT_WITHOUT_FIELDER": case "NAMESUPER": case "FALLOFWICKET": case "NAMESUPER-PLAYER": case "SPLIT": case "BATSMANSTATS":
			case "BOWLERSTATS": case "PLAYERSUMMARY": case "BOWLERDETAILS": case "TEAMSUMMARY": case "PROJECTED": case "BATSMAN_STYLE": case "BOWLER_STYLE": case "PLAYERPROFILEBAT":
			case "PLAYERPROFILE": case "PARTNERSHIP": case "SEASON_PROFILE": case "THISSERIES": case "THISPARTNERSHIP": case "NEXT_TO_BAT": case "IMPACT": case "PHASE-WISE":
			case "PHASE-COMPARISON": case "LT_POINTER":
				print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
						+ " C:/Temp/Preview.tga LT$LTBaseIn 0.0 LT$LTLogoIn 0.0 "
						+ "LT$LTDataIn 0.0 LT$LTBase2In 1.700 LT$LTLogo2In 1.660 LT$LTData2In 2.100 \0");
				TimeUnit.MILLISECONDS.sleep(500);
				break;
			case "BAT-POPUP": case "BOWL-POPUP":
				print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene+ " C:/Temp/Preview.tga In 1.70 Change 1.0\0");
				break;
			}
		}
	}

