	public void PerformerPreview(PrintWriter print_writer, String viz_scene, int which_side, String which_graphic)
			throws InterruptedException {
		if (which_side == 1) {
			switch (which_graphic) {
			case "BAT_PERFORMER":
				print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
						+ " C:/Temp/Preview.tga anim_FullFrames 2.660 anim_FullFrames$In_Out$Essentials$In 1.240 "
						+ "anim_FullFrames$In_Out$Main$BattingCard$In 2.540 anim_FullFrames$In_Out$Main$BatExtraData$BatPerformer$In 2.660 anim_FullFrames$In_Out$Footer$In 2.560 \0");
				TimeUnit.MILLISECONDS.sleep(500);
				break;
			case "BAT_PARTNERSHIP":
				print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
						+ " C:/Temp/Preview.tga anim_FullFrames 2.660 anim_FullFrames$In_Out$Essentials$In 1.240 "
						+ "anim_FullFrames$In_Out$Main$BattingCard$In 2.540 anim_FullFrames$In_Out$Main$BatExtraData$BatPartnership$In 2.660 anim_FullFrames$In_Out$Footer$In 2.560 \0");
				TimeUnit.MILLISECONDS.sleep(500);
				break;
			case "BALL_PERFORMER":
				print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
						+ " C:/Temp/Preview.tga anim_FullFrames 2.660 anim_FullFrames$In_Out$Essentials$In 1.240 "
						+ "anim_FullFrames$In_Out$Main$BowlingCard$In 2.540 anim_FullFrames$In_Out$Main$BowlingExtraData$BallPerformer$In 2.660 anim_FullFrames$In_Out$Footer$In 2.560 \0");
				TimeUnit.MILLISECONDS.sleep(500);
				break;
			}
		} else if (which_side == 2) {
			String p_graphic = "", n_graphic = "", BatOrBall = "";
			switch (which_graphic_on_screen) {
			case "BATBALLSUMMARY_SCORECARD_PERFORMER":
				p_graphic = "Change$Main$BatExtraData$BatPerformer$Change_Out 1.060";
				break;
			case "BATBALLSUMMARY_SCORECARD_PARTNERSHIP":
				p_graphic = "Change$Main$BatExtraData$BatPartnership$Change_Out 1.060";
				break;
			case "BATBALLSUMMARY_BOWLINGCARD_PERFORMER":
				p_graphic = "Change$Main$BowlingExtraData$BallPerformer$Change_Out 1.060";
				break;
			}

			switch (which_graphic) {
			case "BAT_PERFORMER":
				BatOrBall = "anim_FullFrames$In_Out$Main$BattingCard$In 2.500";
				n_graphic = "Change$Main$BatExtraData$BatPerformer$Change_In 1.700";
				TimeUnit.MILLISECONDS.sleep(500);
				break;
			case "BAT_PARTNERSHIP":
				BatOrBall = "anim_FullFrames$In_Out$Main$BattingCard$In 2.500";
				n_graphic = "Change$Main$BatExtraData$BatPartnership$Change_In 1.700";
				TimeUnit.MILLISECONDS.sleep(500);
				break;
			case "BALL_PERFORMER":
				BatOrBall = "anim_FullFrames$In_Out$Main$BowlingCard$In 2.500";
				n_graphic = "Change$Main$BowlingExtraData$BallPartnership$Change_In 1.700";
				TimeUnit.MILLISECONDS.sleep(500);
				break;
			}

			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene
					+ " C:/Temp/Preview.tga anim_FullFrames 2.660 anim_FullFrames$In_Out$Essentials$In 1.240 " + ""
					+ BatOrBall + p_graphic + " " + n_graphic + " anim_FullFrames$In_Out$Footer$In 2.560 \0");
			TimeUnit.MILLISECONDS.sleep(500);
		}
	}

	public void populateInfobarPlayerStats(Infobar infobar, boolean is_this_updating, PrintWriter printWriter,
			int teamId, int playerId, String playerType, String Profile, MatchAllData match, Statistics stats,
			String broadcaster) {
		Player plyr = getPlayerFromMatchData(stats.getPlayer_id(), match);
		if (plyr.getTeamId() == match.getSetup().getHomeTeamId()) {
			System.out.println("HOME : " + plyr.getFirstname());
		} else {
			System.out.println("Away : " + plyr.getFirstname());
		}
		switch (playerType.toUpperCase()) {
		case "BAT":
			if (Profile.toUpperCase().equalsIgnoreCase(CricketUtil.DT20)
					|| Profile.toUpperCase().equalsIgnoreCase(CricketUtil.IT20)
					|| Profile.toUpperCase().equalsIgnoreCase(CricketUtil.ODI)
					|| Profile.toUpperCase().equalsIgnoreCase("LLCS1")) {
				System.out
						.println(" stats.getMatches() : " + stats.getMatches() + " stats.Runs() : " + stats.getRuns());

			}
			break;
		}
	}
	public void adjustManhattanAccordingToReducedOvers(PrintWriter print_writer, int totalOvers) throws InterruptedException {
		
		int numTransformDiff = 0;
		int barsTransformDiff = 0;
		//hiding bars 
		for(int i=1; i<=20; i++) {
			print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side1$ManhattanGraphics$MahattanDataOut$ManhattanGrp$Graph$Bars$Out$Position$"+i+"*ACTIVE SET 0\0");
		}
		//setting bar grids and opening eye
//		print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side1$ManhattanGraphics$MahattanDataOut$ManhattanGrp$Graph$Bars$Out$Position*FUNCTION*Grid*num_col SET "
//				+ totalOvers + "\0");
		for(int i=1; i<=totalOvers; i++) {
			print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side1$ManhattanGraphics$MahattanDataOut$ManhattanGrp$Graph$Bars$Out$Position$"+i+"*ACTIVE SET 1\0");
		}
		if(totalOvers>=10) {
			//overs adjustments
			numTransformDiff = 0;
			barsTransformDiff = 0;
			for(int i=1; i<=10; i++) {
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side1$ManhattanGraphics$MahattanDataOut$ManhattanGrp$Graph$Overs_Axis$Posiiton$Out$In$Data"
								+ "$Position$Arrange$txt_" + i + "*GEOM*TEXT SET " + i * 2 + "\0");
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side1$ManhattanGraphics$MahattanDataOut$ManhattanGrp$Graph$Overs_Axis$Posiiton$Out$In$Data"
								+ "$Position$Arrange$txt_" + i + "*TRANSFORMATION*POSITION*X SET " + (numTransformDiff*86) + "\0");
				numTransformDiff++;
			}
			
			//bars adjustment
			print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side1$ManhattanGraphics$MahattanDataOut$ManhattanGrp$Graph$Bars$Out$Position*FUNCTION*Grid*col_offset SET 43\0");
			for(int i=1; i<=totalOvers; i++) {
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side1$ManhattanGraphics$MahattanDataOut$ManhattanGrp$Graph$Bars$Out$Position$"+i+"*TRANSFORMATION*SCALING*LOCK SET 1\0");
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side1$ManhattanGraphics$MahattanDataOut$ManhattanGrp$Graph$Bars$Out$Position$"+i+"*TRANSFORMATION*SCALING*X SET 1\0");
				barsTransformDiff++;
			}
		}else if(totalOvers >0 && totalOvers < 10) {
			numTransformDiff = 0;
			barsTransformDiff = 0;
			for(int i=1; i<=10; i++) {
				switch(i) {
				case 1:
					numTransformDiff = -43;
					break;
				case 2:
					numTransformDiff = 46;
					break;
				case 3:
					numTransformDiff = 137;
					break;
				case 4:
					numTransformDiff = 229;
					break;
				case 5:
					numTransformDiff = 319;
					break;
				case 6:
					numTransformDiff = 410;
					break;
				case 7:
					numTransformDiff = 501;
					break;
				case 8:
					numTransformDiff = 592;
					break;
				case 9:
					numTransformDiff = 686;
					break;
				case 10:
					numTransformDiff = 774;
					break;
				}
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side1$ManhattanGraphics$MahattanDataOut$ManhattanGrp$Graph$Overs_Axis$Posiiton$Out$In$Data"
								+ "$Position$Arrange$txt_" + i + "*GEOM*TEXT SET " + i + "\0");
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side1$ManhattanGraphics$MahattanDataOut$ManhattanGrp$Graph$Overs_Axis$Posiiton$Out$In$Data"
						+ "$Position$Arrange$txt_" + i + "*TRANSFORMATION*POSITION*X SET " + numTransformDiff + "\0");
			}
			//bars adjustment
			print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side1$ManhattanGraphics$MahattanDataOut$ManhattanGrp$Graph$Bars$Out$Position*FUNCTION*Grid*col_offset SET 91\0");
			for(int i=1; i<=totalOvers; i++) {
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side1$ManhattanGraphics$MahattanDataOut$ManhattanGrp$Graph$Bars$Out$Position$"+i+"*TRANSFORMATION*SCALING*LOCK SET 1\0");
				print_writer.println("-1 RENDERER*BACK_LAYER*TREE*$Main$All_Fullframes$Side1$ManhattanGraphics$MahattanDataOut$ManhattanGrp$Graph$Bars$Out$Position$"+i+"*TRANSFORMATION*SCALING*X SET 1.5\0");
				barsTransformDiff++;
			}
		}
	}

